import type { LocaleId } from '../locales';
import type { LegalSection } from '@/components/layout/LegalDocumentPage';
import { DD_CONTACT } from '@/lib/legal/legalMeta';

export type PrivacyCopy = {
  title: string;
  description: string;
  metaDescription: string;
  cta: string;
  sections: LegalSection[];
};

const site = DD_CONTACT.site;
const support = DD_CONTACT.support;
const brand = DD_CONTACT.brand;

type Pack = {
  title: string;
  description: string;
  meta: string;
  cta: string;
  h: string[];
  b: string[][];
  bullets?: Record<number, string[]>;
};

const ids = [
  'who-we-are',
  'scope',
  'information-we-collect',
  'information-we-do-not-sell',
  'how-we-use',
  'legal-bases-us',
  'local-storage',
  'third-parties',
  'ai-features',
  'retention',
  'security',
  'children',
  'your-rights',
  'do-not-track',
  'international',
  'changes',
  'contact',
] as const;

function pack(locale: Pack): PrivacyCopy {
  return {
    title: locale.title,
    description: locale.description,
    metaDescription: locale.meta,
    cta: locale.cta,
    sections: ids.map((id, index) => ({
      id,
      heading: locale.h[index],
      body: locale.b[index],
      bullets: locale.bullets?.[index],
    })),
  };
}

